import assert from "node:assert/strict";

import { decodeAttributedBody } from "./pollVotes";

// A REAL streamtyped `attributedBody` blob pulled from chat.db (ROWID 27208) — a message
// whose `text` column is NULL on this machine, so the plain body lives only in this blob.
// Header … NSString … `+` (0x2b) … 0x81 <UInt16LE len=732> … UTF-8 text … attribute runs.
const REAL_ATTRIBUTED_BODY_HEX =
  "";

function testDecodeRealBlob(): void {
  const text = decodeAttributedBody(REAL_ATTRIBUTED_BODY_HEX);
  // The `text` column was NULL for this row; decode must recover the real body.
  assert.ok(
    text.startsWith("yeah, i agree - same file, marked. keeping them in the one log"),
    `expected decoded reply text, got: ${JSON.stringify(text.slice(0, 60))}`,
  );
  // Length-bounded slice: must stop at the string payload, not bleed into the attribute runs.
  assert.equal(text.length, 732, `expected 732-byte payload, got ${text.length}`);
  assert.ok(!text.includes("NSDictionary"), "decode must not spill into trailing attribute runs");
}

function testShortSingleByteLength(): void {
  // Hand-built minimal blob: `NSString` + `+` (0x2b) + single-byte length (5) + "hello".
  const hex = Buffer.concat([
    Buffer.from("NSString", "latin1"),
    Buffer.from([0x01, 0x94, 0x84, 0x01, 0x2b, 0x05]),
    Buffer.from("hello", "utf8"),
  ]).toString("hex");
  assert.equal(decodeAttributedBody(hex), "hello");
}

function testDefensiveFailures(): void {
  assert.equal(decodeAttributedBody(""), "", "empty hex → empty string");
  assert.equal(decodeAttributedBody("zzzz"), "", "invalid hex → empty string (never throws)");
  assert.equal(decodeAttributedBody("deadbeef"), "", "no NSString anchor → empty string");
  // Anchor + marker present but length runs past the buffer → empty, no throw/overrun.
  const truncated = Buffer.concat([
    Buffer.from("NSString", "latin1"),
    Buffer.from([0x2b, 0xff]),
    Buffer.from("hi", "utf8"),
  ]).toString("hex");
  assert.equal(decodeAttributedBody(truncated), "", "length past end → empty string");
}

function main(): void {
  testDecodeRealBlob();
  testShortSingleByteLength();
  testDefensiveFailures();
  console.log("pollVotes attributedBody decode tests passed");
}

main();
